import {ROOMS,EQUIPMENT} from '../data/rooms.js'; import {NOW,NOW_LABEL} from '../config.js'; import {createStore} from '../state/store.js'; import {roomCard,bookings,status} from './render.js';
const app=document.querySelector('#app'); const store=createStore({rooms:ROOMS,now:NOW});
function render(view){ const {state,matching,room,availability}=view; app.innerHTML=`<header class="hero"><div><p class="eyebrow">CAMPUSPULSE / SMART CAMPUS</p><h1>Room Scout</h1><p>Find a room that fits your group, equipment and time window.</p></div><div class="clock"><span>SIMULATED NOW</span><strong>${NOW_LABEL}</strong><small>Max 120 min</small></div></header><main class="layout"><aside class="filters panel"><h2>1. Set requirements</h2><label>Attendees<input id="attendees" type="number" min="1" value="${state.attendees}"></label><fieldset><legend>Required equipment</legend>${EQUIPMENT.map(x=>`<label class="chip"><input type="checkbox" data-eq="${x}" ${state.equipment.includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</fieldset><div class="match-count"><strong>${matching.length}</strong><span>matching room${matching.length===1?'':'s'}</span></div></aside><section class="rooms panel"><div class="section-head"><div><h2>2. Choose a room</h2><p>Only rooms matching every selected requirement appear.</p></div></div><div class="room-grid">${matching.length?matching.map(r=>roomCard(r,r.id===state.selectedRoomId)).join(''):'<div class="empty"><strong>No rooms match</strong><span>Reduce attendees or remove an equipment requirement.</span></div>'}</div></section><section class="checker panel"><h2>3. Check availability</h2>${room?`<div class="selected-summary"><div><span>Selected room</span><strong>${room.name}</strong></div><span class="capacity">${room.capacity} seats</span></div><div class="time-row"><label>Start<input id="start" type="time" value="${state.start}"></label><label>End<input id="end" type="time" value="${state.end}"></label></div><button id="check" class="primary">Check availability</button>${status(availability)}<div class="bookings"><h3>Existing bookings</h3><ul>${bookings(room)}</ul></div>`:'<div class="empty tall"><strong>No room selected</strong><span>Adjust the filters to reveal a room.</span></div>'}</section></main><footer>Fictional classroom data · No login · No database · No live API</footer>`;
  document.querySelector('#attendees')?.addEventListener('input',e=>store.setAttendees(e.target.value)); document.querySelectorAll('[data-eq]').forEach(el=>el.addEventListener('change',()=>store.toggleEquipment(el.dataset.eq))); document.querySelectorAll('[data-room]').forEach(el=>el.addEventListener('click',()=>store.selectRoom(el.dataset.room))); document.querySelector('#check')?.addEventListener('click',()=>{store.setTime(document.querySelector('#start').value,document.querySelector('#end').value);store.check();});
}
store.subscribe(render);
